  "Type it at “Sign in with password” instead of your profile name. We never send anything to it; a forgotten password is still reset by your admin.": "Įveskite jį „Prisijungti slaptažodžiu“ vietoj profilio vardo. Jokių pranešimų į jį niekada nesiunčiama; pamirštą slaptažodį vis tiek atstatys jūsų administratorius.",
