  "1 passkey": "1 prieigos raktas",
  "A one-time code lets your phone or another computer sign in with a passkey of its own.": "Vienkartinis kodas leidžia jūsų telefonui ar kitam kompiuteriui prisijungti naudojant savo prieigos raktą.",
  "Add a passkey": "Pridėti prieigos raktą",
