  "Code from your other device": "Kodas iš kito jūsų įrenginio",
  "Confirm with a passkey": "Patvirtinti prieigos raktu",
  "Confirmed. Now create the new passkey; your browser will ask where to keep it.": "Patvirtinta. Dabar sukurkite naują prieigos raktą; naršyklė paklaus, kur jį saugoti.",
  "Copy link": "Kopijuoti nuorodą",
  "Create a passkey on this device for the profile “{0}”. It signs you in here from now on.": "Šiame įrenginyje sukurkite prieigos raktą profiliui „{0}“. Nuo šiol jis leis prisijungti čia.",
  "Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.": "Kiekvienas leidžia prisijungti prie šio profilio iš įrenginio ar slaptažodžių valdytojo, kuriame jis saugomas. Palieskite, kad pakeistumėte pavadinimą arba pašalintumėte.",
  "Enter the code from your other device.": "Įveskite kodą iš kito jūsų įrenginio.",
  "For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.": "Šiam įrenginiui: saugos raktas, slaptažodžių valdytojas arba jūsų telefonas per naršyklės QR kodą. Pirmiausia patvirtinkite, kad tai jūs.",
  "It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.": "Jis nebeleidžia prisijungti prie šio profilio. Įrenginys, kuris jau prisijungė juo, lieka prisijungęs. Jei jis buvo prarastas, naudokite „Atsijungti visur“.",
  "It is your only way in, so it cannot be removed until there is another.": "Tai jūsų vienintelis būdas patekti, todėl jo negalima pašalinti, kol nebus kito.",
  "Last used {0}": "Paskutinį kartą naudota {0}",
  "Make a new code": "Sukurti naują kodą",
  "Name, e.g. Work laptop": "Pavadinimas, pvz., Darbo nešiojamas kompiuteris",
  "None yet. Add one and sign in without your password.": "Dar nėra. Pridėkite vieną ir prisijunkite be slaptažodžio.",
  "Passkey added": "Prieigos raktas pridėtas",
  "Passkey removed": "Prieigos raktas pašalintas",
  "Passkey {0}": "Prieigos raktas {0}",
  "Passkeys": "Prieigos raktai",
  "Remove passkey": "Pašalinti prieigos raktą",
  "Remove this passkey?": "Pašalinti šį prieigos raktą?",
  "Scan this with the other device, or open openGym there and enter the code on the sign-in screen. It works once, for {0} minutes.": "Nuskenuokite tai kitu įrenginiu arba atidarykite ten „openGym“ ir įveskite kodą prisijungimo ekrane. Jis veikia vieną kartą, {0} min.",
  "That code is wrong, already used or expired. Make a new one on your other device.": "Neteisingas kodas, jau panaudotas arba pasibaigęs. Sukurkite naują kitame įrenginyje.",
  "This browser cannot confirm with your passkey. Do this on a device that holds one.": "Ši naršyklė negali patvirtinti tapatybės su jūsų prieigos raktu. Atlikite tai įrenginyje, kuriame jis saugomas.",
  "First confirm that it is you.": "Pirmiausia patvirtinkite, kad tai esate jūs.",
  "This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.": "Šiame profilyje nėra prieigos rakto, o šis serveris nepriima slaptažodžių, todėl niekas čia negali patvirtinti jūsų tapatybės. Kreipkitės į administratorių.",
  "This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.": "Ši naršyklė negali kurti prieigos raktų, todėl jos negalima pridėti naudojant kodą. Atidarykite nuorodą naršyklėje, kuri tai palaiko.",
  "This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.": "Ši naršyklė prisijungusi kaip „{0}“. Pridėjus ją prie „{1}“, čia bus atjungta „{0}“.",
  "This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.": "Šis kodas skirtas kitam profilui, kuris taip pat vadinasi „{0}“, o ne tam, kuris prisijungęs šioje naršyklėje. Pridėjus jį ten, jūsų profilis čia bus atjungtas.",
  "Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.": "Tęskite tik jei šis kodas yra iš jūsų įrenginio. Tada ši naršyklė prisijungs prie „{0}“, o čia įvesti duomenys bus priskirti tam profilui.",
  "This code has expired.": "Šis kodas pasibaigęs.",
  "This device already has a passkey for this profile.": "Šiame įrenginyje jau yra prieigos raktas šiam profilui.",
  "This passkey already belongs to a profile.": "Šis prieigos raktas jau priklauso profilui.",
