  "Use a code from your other device": "Naudokite kodą iš kito įrenginio",
  "You get a code that lets your phone or another computer create a passkey for this profile. First confirm that it is you.": "Gaukite kodą, kuris leis jūsų telefonui ar kitam kompiuteriui sukurti prieigos raktą šiam profilui. Pirmiausia patvirtinkite, kad tai esate jūs.",
  "or with your password": "arba su slaptažodžiu",
