  "Saves a dated copy to Documents/openGym after finishing a workout or editing a routine, and keeps the newest {0}. Point a sync app at that folder, or copy it out by hand.": "Baigus treniruotę arba redaguojant programą, sukuriama datos kopija aplanke Documents/openGym ir išsaugoma naujausių {0} kopijų. Nukreipkite sinchronizavimo programą į šį aplanką arba nukopijuokite ją rankiniu būdu.",
  "Reset everything?": "Ar iš naujo nustatyti viską?",
  "Reset everything": "Iš naujo nustatyti viską",
  "Deletes your plan, workouts, body weight, photos and videos on this device. This cannot be undone.": "Ištrina jūsų planą, treniruotes, kūno svorį, nuotraukas ir vaizdo įrašus šiame įrenginyje. Šio veiksmo negalima atšaukti.",
  "Deletes your plan, workouts, body weight, photos and videos from your profile on this server and on every signed-in device. This cannot be undone.": "Ištrina jūsų planą, treniruotes, kūno svorį, nuotraukas ir vaizdo įrašus iš jūsų profilio šiame serveryje ir visuose prisijungusiuose įrenginiuose. Šio veiksmo negalima atšaukti.",
  "Sync failed: the server refused the upload as too large. Your changes have not reached the server.": "Sinchronizavimas nepavyko: serveris atmetė įkėlimą dėl per didelio dydžio. Jūsų pakeitimai nepasiekė serverio.",
