  "Estimated 1RM": "Apytikslis 1RM",
  "Estimated 1RM per workout": "Apytikslis 1RM pagal treniruotę",
  "Best estimate from {0} on {1}. An estimate, not a tested max.": "Geriausias apytikslis vertinimas iš {0} {1} d. Tai apytikslis vertinimas, o ne išbandytas maksimumas.",
