  "The Coach is on": "Treneris įjungtas",
  "the configured AI provider": "konfigūruotą DI tiekėją",
  "Your name, your sign-in details and everything else about your account stay here. Other people’s data is never included.": "Jūsų vardas, prisijungimo duomenys ir visa kita apie jūsų paskyrą saugoma čia. Kitų žmonių duomenys niekada neįtraukiami.",
  "The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "„Coach“ nėra gydytojas ar fizioterapeutas. Jei jaučiama skausmas, kreipkitės į specialistą.",
  "Not now": "Ne dabar",
  "Meet the Coach": "Susipažinkite su „Coach“",
  "Review": "Peržiūrėti",
  "Automatic reviews": "Automatinės peržiūros",
  "Off. The Coach only looks when you ask.": "Išjungta. „Coach“ žiūri tik tada, kai paprašote.",
  "You are only notified when the Coach actually has something to suggest.": "Jūs gaunate pranešimą tik tada, kai „Coach“ turi ką nors pasiūlyti.",
