  "min": "min.",
  "The Coach fits the volume to the time you actually have, including rest between sets.": "Treneris pritaiko apkrovą pagal jūsų turimą laiką, įskaitant poilsį tarp serijų.",
  "What can you train with?": "Su kuo galite treniruotis?",
  "Pick everything you have access to. Leave it empty and the Coach will use the whole library.": "Pasirinkite viską, prie ko turite prieigą. Palikite tuščią, ir Treneris naudos visą pratimų biblioteką.",
  "Anything to work around?": "Ar yra ką apsukti?",
  "Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.": "Sužalojimai, skaudantys sąnariai, negalimi judesiai ar praktiniai apribojimai, pvz., treniruotės 6 val. ryte bute.",
  "e.g. “dodgy left shoulder, no barbell overhead press”": "pvz., „kairė peties sąnario problema, negaliu atlikti spaudimo virš galvos su štanga“",
  "If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.": "Jei kas nors tikrai skauda, kreipkitės į specialistą. Treneris programuos atsargiai, bet negali nieko diagnozuoti.",
  "Anything else?": "Ar yra ką nors dar?",
  "Exercises you love": "Pratimai, kuriuos mėgstate",
  "e.g. “deadlifts, anything with a kettlebell”": "pvz., „mirties traukimas, bet kas su kankinu“",
  "Exercises you would rather not": "Pratimai, kurių norėtumėte išvengti",
  "e.g. “I hate lunges”": "pvz., „nekenčiu žingsnių“",
  "Anything you want the Coach to know": "Ką nors, ką norėtumėte, kad Treneris žinotų",
  "e.g. “I want visible arms progress by spring”": "pvz., „noriu matomų rankų progresų iki pavasario“",
  "Build my plan": "Sukurti mano planą",
  "Your plan is live": "Jūsų planas aktyvus",
  "That proposal can’t be read.": "Šio pasiūlymo negalima perskaityti.",
  "Discard this plan?": "Atmesti šį planą?",
  "Nothing is saved, and you can ask again anytime.": "Nieko neišsaugoma. Naujo plano galite paprašyti bet kada.",
  "Revision {0}": "Peržiūra {0}",
  "Replaces your current week. Days this plan leaves empty become rest days.": "Pakeičia jūsų dabartinę savaitę. Dienos, kurias šis planas palieka tuščias, tampa poilsio dienomis.",
  "Could not apply those changes": "Nepavyko pritaikyti tų pakeitimų",
  "Dismiss these suggestions?": "Atmesti šiuos pasiūlymus?",
  "Nothing changes, and the Coach will remember you turned these down.": "Nieko nekeičiama, o Treneris prisimins, kad atmetėte šiuos pasiūlymus.",
  "Dismiss": "Atmesti",
  "Based on your last {0} sessions": "Remiantis jūsų paskutinėmis {0} treniruotėmis",
  "Your plan changed since the Coach looked at it. Suggestions that no longer match are greyed out. Ask for a fresh review to see them again.": "Jūsų planas pasikeitė nuo to laiko, kai Treneris jį peržiūrėjo. Pasiūlymai, kurie nebeatitinka, yra išryškinti pilka spalva. Prašykite naujos peržiūros, kad juos matytumėte vėl.",
