  "Filters the exercise library and picker, and flags routine exercises that need something you don’t have in the active profile.": "Filtruoja pratimų biblioteką bei parinkiklį ir pažymi programos pratimus, kuriems reikia aktyviame profilyje nenurodytos įrangos.",
