  "{0} minutes is long. Rest periods may be creeping up.": { one: "{0} min. – tai ilgas laikas. Poilsio intervalai gali šiek tiek pailgėti.", few: "{0} min. – tai ilgas laikas. Poilsio intervalai gali šiek tiek pailgėti.", many: "{0} min. – tai ilgas laikas. Poilsio intervalai gali šiek tiek pailgėti.", other: "{0} min. – tai ilgas laikas. Poilsio intervalai gali šiek tiek pailgėti." },
  "Top sets logged without an effort rating; add RIR so the next review can read how hard they were.": "Geriausios serijos įrašytos be pastangų įvertinimo; įtraukite RIR, kad kitą kartą būtų matyti, kaip sunkios jos buvo.",
  "Add the next load step on the main lift.": "Pridėkite kitą svorio žingsnį pagrindiniame judesyje.",
  "Repeat the same loads and get every set.": "Pakartokite tuos pačius svorius ir atlikite visas serijas.",
  "Keep the session under an hour and a quarter.": "Laikykite treniruotę trumpesnę nei 1 val. 15 min.",
  "A clean session: everything on the sheet got done and the loads held. This is exactly what progress looks like from the inside: unremarkable, repeated.": "Švari treniruotė: viskas pagal planą atlikta ir svoriai išlaikyti. Būtent taip iš vidaus atrodo progresas: paprasta, kartojama.",
  "Most of the work got done. One or two sets fell short, which is fine once. It only becomes a signal if the same sets miss next time.": "Dauguma darbo atlikta. Viena ar dvi serijos liko neatliktos – tai normalu vieną kartą. Tai tampa signalu tik jei tos pačios serijos vėl praleidžiamos kitą kartą.",
