  "Plates": "Diskai",
  "Pairs of each size you own. Every set row loads from this list, so a home gym with one pair of 45s is never told to use two.": "Nurodykite, kiek kiekvieno svorio diskų porų turite. Diskai kiekvienai serijai parenkami iš šio sąrašo, todėl turint vieną 45 svorio diskų porą nebus siūloma naudoti dviejų.",
