  "{0} workouts and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "Šiame įrenginyje, kai nebuvo prisijungta, buvo užfiksuota {0} treniruočių ir {1} svorio matavimų. Pridėkite juos prie savo profilio arba palikite profilį tokį, koks yra serveryje.",
  "{0} workout and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "Šiame įrenginyje, kai nebuvo prisijungta, buvo užfiksuota {0} treniruotė ir {1} svorio matavimas. Pridėkite juos prie savo profilio arba palikite profilį tokį, koks yra serveryje.",
  "{0} workout and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "Šiame įrenginyje, kai nebuvo prisijungta, buvo užfiksuota {0} treniruotė ir {1} svorio matavimai. Pridėkite juos prie savo profilio arba palikite profilį tokį, koks yra serveryje.",
  "{0} workouts and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "Šiame įrenginyje, kai nebuvo prisijungta, buvo užfiksuota {0} treniruotės ir {1} svorio matavimas. Pridėkite juos prie savo profilio arba palikite profilį tokį, koks yra serveryje.",
