  "Not synced yet. Tap to retry.": "Dar nesinchronizuota. Palieskite, kad bandytumėte dar kartą.",
  "Back online and synced with the server.": "Ryšys atkurtas ir sinchronizuota su serveriu.",
  "This phone is not connected to a server.": "Šis telefonas nėra prijungtas prie serverio.",
  "The server did not answer in time.": "Serveris neatsakė per nustatytą laiką.",
  "The server answered with something other than openGym data.": "Serveris atsakė ne openGym duomenimis.",
  "{0} added ({1})": "Pridėta {0} ({1})",
