  "Your server can’t be reached. Your changes are saved on this device and sync once it answers again.": "Nepavyksta pasiekti jūsų serverio. Pakeitimai išsaugoti šiame įrenginyje ir bus sinchronizuoti, kai serveris vėl atsakys.",
  "Your server can’t be reached. Showing the last copy synced with it.": "Nepavyksta pasiekti jūsų serverio. Rodoma paskutinė su juo sinchronizuota kopija.",
  "Server address unknown": "Nežinomas serverio adresas",
  "Pair again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.": "Sujunkite iš naujo arba pirmiausia eksportuokite atsarginę kopiją. Jei tęsite, šių pakeitimų kopija išliks šiame įrenginyje, kol jis vėl prisijungs prie šio serverio šiuo paskyros vardu. Tada jie bus pridėti atgal.",
  "Sign in again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.": "Prisijunkite iš naujo arba pirmiausia eksportuokite atsarginę kopiją. Jei tęsite, šių pakeitimų kopija išliks šiame įrenginyje, kol jis vėl prisijungs prie šio serverio šiuo paskyros vardu. Tada jie bus pridėti atgal.",
