  "That file type isn’t supported. Use a photo, a GIF, or an MP4, MOV or WebM video.": "Šis failo tipas nepalaikomas. Naudokite nuotrauką, GIF arba MP4, MOV ar WebM vaizdo įrašą.",
  "That file is too big. Max {0} MB.": "Šis failas per didelis. Maks. {0} MB.",
  "That video is too long. Max {0} seconds.": "Šis vaizdo įrašas per ilgas. Maks. {0} sekundžių.",
  "That photo is too large to process on this device.": "Ši nuotrauka per didelė, kad būtų apdorota šiame įrenginyje.",
  "You’re offline. Try again once you’re back online.": "Jūs esate neprisijungę. Pabandykite dar kartą, kai vėl prisijungsite.",
  "This browser cannot read that file.": "Ši naršyklė negali perskaityti šio failo.",
  "There is no room left on this device for that file.": "Šiame įrenginyje nebeliko vietos šiam failui.",
  "This video may not play on every device. MP4 (H.264) plays everywhere.": "Šis vaizdo įrašas gali neveikti visuose įrenginiuose. MP4 (H.264) veikia visur.",
