  "The server refused the file as too large.": "Serveris atmetė failą kaip per didelį.",
  "Kept on this device only. Export with photos & videos keeps a copy.": "Išsaugoma tik šiame įrenginyje. Eksportuojant su nuotraukomis ir vaizdo įrašais, išlaikoma kopija.",
  "Your server does not store photos and videos yet.": "Jūsų serveris dar nesaugo nuotraukų ir vaizdo įrašų.",
