  "The server has 1 workout that is not in this backup, logged since it was made or on another device. Replacing deletes it.": "Serveryje yra 1 treniruotė, kurios nėra šioje atsarginėje kopijoje, įregistruota nuo jos sukūrimo arba kitame įrenginyje. Pakeitimas ją ištrins.",
  "The server has {0} workouts that are not in this backup, logged since it was made or on another device. Replacing deletes them.": { one: "Serveryje yra {0} treniruotė, kurios nėra šioje atsarginėje kopijoje, įregistruota nuo jos sukūrimo arba kitame įrenginyje. Pakeitimas ją ištrins.", few: "Serveryje yra {0} treniruotės, kurių nėra šioje atsarginėje kopijoje, įregistruotos nuo jų sukūrimo arba kitame įrenginyje. Pakeitimas jas ištrins.", many: "Serveryje yra {0} treniruotės, kurių nėra šioje atsarginėje kopijoje, įregistruotų nuo jų sukūrimo arba kitame įrenginyje. Pakeitimas jas ištrins.", other: "Serveryje yra {0} treniruočių, kurių nėra šioje atsarginėje kopijoje, įregistruotų nuo jų sukūrimo arba kitame įrenginyje. Pakeitimas jas ištrins." },
