  "{0} sets become {1}: one on each side, {2}s held every time.": { one: "{0} serija tampa {1}: po vieną kiekvienai pusei, {2}s laikoma kiekvieną kartą.", few: "{0} serijos tampa {1}: po vieną kiekvienai pusei, {2}s laikoma kiekvieną kartą.", many: "{0} serijos tampa {1}: po vieną kiekvienai pusei, {2}s laikoma kiekvieną kartą.", other: "{0} serijų tampa {1}: po vieną kiekvienai pusei, {2}s laikoma kiekvieną kartą." },
  "For side planks, single-arm holds and the like. Trains each side on its own.": "Šoniniams planšiuočių, vienos rankos laikymams ir pan. Trenuoja kiekvieną pusę atskirai.",
