  "{0} photo": "{0} nuotrauka",
  "{0} photos": { one: "{0} nuotrauka", few: "{0} nuotraukos", many: "{0} nuotraukos", other: "{0} nuotraukų" },
  "Your server was reached, but it refused the app’s request (CORS). If a reverse proxy such as Traefik adds CORS headers, let requests from {0} through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.": "Jūsų serveris pasiekiamas, tačiau atmetė programėlės užklausą (CORS). Jei atvirkštinis proxy serveris, pvz., Traefik, prideda CORS antraštes, leiskite užklausoms iš {0} būti perduodamoms toliau programėlei openGym nepakeistoms. Žr. „Phone app and CORS“ dokumente docs/SELF_HOSTING.md.",
  "Could not reach {0}. Check the address and that this phone can reach it.": "Nepavyko pasiekti {0}. Patikrinkite adresą ir ar šis telefonas gali jį pasiekti.",
  "The end of a rest or a hold buzzes like an alarm, even in silent mode.": "Poilsio arba laikymo laikotarpio pabaiga skamba kaip signalas, net ir tylos režimu.",
  "Repeat today": "Pakartoti šiandien",
  "Nothing to repeat. Its exercises no longer exist.": "Nėra ką kartoti. Jo pratimų daugiau nebeliko.",
