  "Show connection status": "Rodyti ryšio būseną",
  "Off: the bar at the top is hidden. A dot on Home still warns when syncing is stuck.": "Išjungta: viršutinė juosta paslėpta. Taškas pagrindiniame ekrane vis tiek įspės, jei sinchronizacija sustos.",
