  "This folder can’t be used for backups.": "Šis aplankas negali būti naudojamas atsarginėms kopijoms.",
  "openGym can no longer write to “{0}”, so copies go to Documents/openGym again. Choose the folder again to switch back.": "openGym daugiau negali rašyti į „{0}“, todėl kopijos vėl saugomos aplankuose Documents/openGym. Pasirinkite aplanką iš naujo, kad grįžtumėte.",
  "openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.": "openGym daugiau negali rašyti į pasirinktą aplanką, todėl kopijos vėl saugomos aplankuose Documents/openGym. Pasirinkite aplanką iš naujo, kad grįžtumėte.",
  "Nudge me when I skip a planned workout": "Priminti, kai praleidžiu suplanuotą treniruotę",
  "Nudge tone": "Priminimo tonas",
  "Friendly": "Draugiškas",
  "Guilt trip": "Kaltės jausmas",
  "Drill sergeant": "Seržantas",
  "One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.": "Vienas priminimas suplanuotos treniruotės dienos vakare, jei niekas neužregistruota, tarp 20:00 ir 21:30. Po 3 praleistų dienų iš eilės jis nutyla iki kitos treniruotės.",
  "Everything okay?": "Viskas gerai?",
  "{0} is still waiting. What’s up?": "{0} vis dar laukia. Kas nutiko?",
  "No {0} today? Even a short session tomorrow counts.": "Šiandien be {0}? Net trumpa treniruotė rytoj skaičiuojasi.",
  "Rough day? {0} will keep. Tomorrow is a fresh start.": "Sunki diena? {0} palauks. Rytoj – nauja pradžia.",
  "Hey, {0} didn’t happen today. All good?": "Sveiki, šiandien {0} neįvyko. Viskas gerai?",
  "I miss you": "Ilgiuosi tavęs",
  "{0} waited by the door all evening. For you.": "{0} visą vakarą laukė prie durų. Laukė tavęs.",
  "The barbell asked about you today. I didn’t know what to say.": "Šiandien štanga paklausė apie tave. Nežinojau, ką atsakyti.",
  "Was it something I said? {0} misses you.": "Ar pasakiau ką nors ne taip? {0} tavęs pasiilgo.",
  "I saved you a spot on the bench. It’s still empty.": "Tau palikau vietą ant suoliuko. Ji vis dar tuščia.",
  "Attention, recruit!": "Dėmesio, kareivi!",
  "Your gains are packing their bags. {0} tomorrow, no excuses!": "Tavo rezultatai jau pakuojasi. {0} rytoj, jokių pateisinimų!",
  "{0} doesn’t do itself, recruit. Move it!": "{0} pats savęs neatliks, rekrute. Judėk!",
  "Excuses don’t lift weights. Report for {0} tomorrow!": "Pasiteisinimai kelti svorių nemoka. Rytoj atlik {0}!",
  "Your muscles filed a missing-person report. Show up for {0}!": "Tavo raumenys paskelbė tavęs paiešką. Ateik į treniruotę: {0}!",
  "That address answers, but it isn’t an openGym server. Check the URL.": "Šis adresas atsako, bet tai nėra openGym serveris. Patikrinkite URL.",
  "That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.": "Šis adresas atsako, bet vietoj openGym atsakė prisijungimo puslapis arba proxy taisyklė. Leiskite /api/ eiti į openGym nepakitusį. Žr. „Phone app and CORS“ docs/SELF_HOSTING.md.",
  "Switch sides": "Perjungti puses",
  "Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.": "Baigus treniruotę arba redaguojant programą, išsaugoma datos kopija į „{0}“ ir paliekama naujausia {1}.",
  "Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.": "Baigus treniruotę arba redaguojant programą, išsaugoma datos kopija į pasirinktą aplanką ir paliekama naujausia {0}.",
  "Plan options": "Planavimo parinktys",
  "Your routines in a loop": "Tavo programos cikle",
  "Back to a fixed week?": "Grįžti prie fiksuotų dienų?",
  "The loop stops. Your weekdays stay as they are, and the loop is saved for later.": "Ciklas sustabdomas. Tavo savaitės dienos lieka tokios, kokios yra, o ciklas išsaugomas vėlesniam naudojimui.",
  "Routines in a loop. Whatever is next stays next until you train it, whatever the day.": "Programos cikle. Kas bus toliau, tas ir bus toliau, kol to nepatrениuos, nesvarbu, kokia diena.",
