  "Scroll to 0:00 to turn the rest timer off.": "Slinkite iki 0:00, kad išjungtumėte poilsio laikmatį.",
  "The short break between the bursts of a rest-pause set.": "Trumpa pertrauka tarp intensyvių serijos pakartojimų.",
  "Each exercise can have its own rest too. Set it in the exercise settings of a routine.": "Kiekviena pratimas gali turėti savo poilsio laiką. Nustatykite jį programos pratimo nustatymuose.",
  "iPhone doesn’t let openGym vibrate. A sound or a flash does the job.": "iPhone neleidžia openGym vibruoti. Vietoj to veikia garsas arba blyksnis.",
  "No account, no cloud. Back it up anytime in Data & backup.": "Nėra paskyros, nėra debesijos. Atsarginę kopiją galite sukurti bet kada skiltyje Duomenys ir atsarginės kopijos.",
  "Effort per set is off. Turn it on in Settings → Workout to keep rating.": "Pastangų vertinimas serijoje išjungtas. Įjunkite jį Nustatymai → Treniruotė, kad būtų fiksuojamas vertinimas.",
  "Enter the code your other device shows under Settings → Account → Add another device. This device then gets a passkey of its own.": "Įveskite kodą, kurį rodo kitas jūsų įrenginys skiltyje Nustatymai → Paskyra → Pridėti kitą įrenginį. Šis įrenginys tada gaus savo slaptažodį.",
  "Open Settings → Account → “Pair the mobile app” on the openGym site you’re already signed into, then enter its address and the code shown there.": "Atidarykite Nustatymai → Paskyra → „Susieti mobiliosios programėlės“ svetainėje openGym, kur jau esate prisijungę, tada įveskite jos adresą ir ten rodomą kodą.",
  "Open Settings → Account → “Pair the mobile app” on your openGym site in a browser and enter the new code shown there. What this phone kept is merged into your account.": "Atidarykite Nustatymai → Paskyra → „Susieti mobiliosios programėlės“ savo openGym svetainėje naršyklėje ir įveskite naują ten rodomą kodą. Tai, ką išsaugojo šis telefonas, bus sujungta su jūsų paskyra.",
  "Change the time left": "Keisti likusį laiką",
