  "Copy this exercise’s warm-up sets, and the rest and note from its Exercise settings, into the routine. A note added for today stays with this workout. Your workout history is kept.": "Nukopijuokite šio pratimo apšilimo serijas, poilsio laiką ir pastabą iš jo pratimo nustatymų į programą. Šiandienai pridėta pastaba išliks su šia treniruote. Jūsų treniruočių istorija bus išsaugota.",
