  "Your plan, notes or gym cards on this device were set up while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "Šio įrenginio planas, pastabos ar treniruočių kortelės buvo sukonfigūruoti esant neprisijungus. Pridėkite juos į savo profilį arba palikite profilį tokį patį, koks yra serveryje.",
  "{0} routine was made on this device while signed out. Add it to your profile, or keep the profile exactly as it is on the server.": "Šio įrenginio programa {0} buvo sukurta esant neprisijungus. Pridėkite ją į savo profilį arba palikite profilį tokį patį, koks yra serveryje.",
  "{0} routines were made on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": { one: "Šiame įrenginyje neprisijungus sukurtų programų: {0}. Pridėkite jas į savo profilį arba palikite profilį tokį, koks yra serveryje.", few: "Šiame įrenginyje neprisijungus sukurtų programų: {0}. Pridėkite jas į savo profilį arba palikite profilį tokį, koks yra serveryje.", many: "Šiame įrenginyje neprisijungus sukurtų programų: {0}. Pridėkite jas į savo profilį arba palikite profilį tokį, koks yra serveryje.", other: "Šiame įrenginyje neprisijungus sukurtų programų: {0}. Pridėkite jas į savo profilį arba palikite profilį tokį, koks yra serveryje." },
