  "Could not reach {0} over https://. If your server runs on plain http (common at home), type http://{0} instead.": "Nepavyko pasiekti {0} per https://. Jei jūsų serveris veikia su paprastu http (dažna situacija namuose), vietoj to įveskite http://{0}.",
