  "Each set one step lighter than the one before. The weight above is the first set.": "Kiekviena serija lengvesnė nei prieš tai buvusi. Viršuje nurodytas svoris pirmajai serijai.",
  "Sets open at {0}. The first set goes up when every set reaches its reps, and the rest follow it.": "Serijos atsidaro esant {0}. Pirmoji serija didėja, kai kiekviena serija pasiekia numatytus pakartojimus, o likusios seka paskui.",
  "The first set goes up when every set reaches its reps, and the rest follow it.": "Pirmoji serija didėja, kai kiekviena serija pasiekia numatytus pakartojimus, o likusios seka paskui.",
