  "Weight means": "Svoris reiškia",
  "The weight of the one you hold. One arm, so it counts once.": "Vieno laikymo svoris. Viena ranka, todėl skaičiuojama vieną kartą.",
  "The weight of one, so 20 means 20 in each hand. Volume counts both.": "Vieno laikymo svoris, todėl 20 reiškia 20 kiekvienoje rankoje. Apimtis skaičiuojama abiem.",
  "Both together, so 40 means two 20s.": "Abiem kartu, todėl 40 reiškia du po 20.",
  "Counted as you type it, the way it always was.": "Skaičiuojama rašant, kaip ir visada.",
  "You’ve outgrown the rack: {0} {1} is your heaviest dumbbell, so the weight stays.": "Jūs išaugote iš stovo: {0} {1} yra sunkiausias hantelis, todėl svoris išlieka.",
  "Dumbbells": "Hanteliai",
  "The weights you own, one bell each. Progression, deloads, warm-ups and the + and − buttons of dumbbell lifts land only on these.": "Jūsų turimi hanteliai, po vieną kiekvieną. Progresa, dešaržas, apšilimai ir hantelių pratimų + bei − mygtukai taikomi tik jiems.",
  "No list yet, so dumbbell lifts step by their increment as usual.": "Sąrašo dar nėra, todėl hantelio pakėlimai žingsniuoja pagal savo didinimą, kaip įprasta.",
  "Fill in {0} to {1} {2}, every {3}": "Užpildykite nuo {0} iki {1} {2}, kas {3}",
  "Clear the list": "Išvalyti sąrašą",
  "Any weight. Tap to list the ones you own.": "Bet koks svoris. Bakstelėkite, kad sąraše būtų rodomi jūsų turimi svoriai.",
  "F": "F",
  "Taken to failure": "Iki visiško išsekimo",
  "Nothing left in the tank": "Nieko nebeliko",
  "Last set to failure": "Paskutinė serija iki visiško išsekimo",
  "The last set goes until nothing is left, and counts as all-out effort unless you rate it.": "Paskutinė serija atliekama iki visiško išsekimo ir skaičiuojama kaip maksimalus pastangų lygis, nebent įvertinsite kitaip.",
  "Plan the final set as an all-out one.": "Planuokite paskutinę seriją kaip maksimalaus pastangų lygio.",
  "Triple progression": "Trikartė progresija",
  "Reps climb to the top of the range, then a set is added, up to your most sets. All of them at the top and the weight goes up, back to your first sets and reps.": "Pakartojimai didėja iki diapazono viršaus, tada pridedama serija, iki jūsų maksimalaus serijų skaičiaus. Visos serijos pasiekus viršų ir svoris padidinamas, grįžtama prie pirmųjų serijų ir pakartojimų.",
  "Same weight, aim for {0} reps in every set.": "Tas pats svoris, siekite {0} pakartojimų kiekvienoje serijoje.",
  "Same weight, aim for {0} reps on the last set.": "Tas pats svoris, siekite {0} pakartojimų paskutinėje serijoje.",
  "{0} reps in every set! Add a set at {1} reps.": "{0} pakartojimai kiekvienoje serijoje! Pridėkite seriją su {1} pakartojimais.",
  "Top of the range on all {0} sets. {1} {2} more, back to {3} sets of {4}.": "Diapazono viršus visose {0} serijose. {1} {2} daugiau, grįžkite prie {3} serijų po {4}.",
  "Top of the range on all {0} sets. {1} {2} less help, back to {3} sets of {4}.": "Diapazono viršus visose {0} serijose. {1} {2} mažiau pagalbos, grįžkite prie {3} serijų po {4}.",
  "Short of the target, but more reps than before. Same sets and reps again.": "Tikslas nepasiektas, bet daugiau pakartojimų nei prieš tai. Tas pats serijų ir pakartojimų skaičius.",
  "Missed reps last time. Same sets and reps again ({0} of {1} to go).": "Praleisti pakartojimai paskutinį kartą. Tas pats serijų ir pakartojimų skaičius vėl ({0} iš {1} liko).",
  "Stuck for {0} sessions. Deload to {1} {2} and start again at {3} sets of {4}.": "Per {0} treniruotes nepadarėte pažangos. Sumažinkite svorį iki {1} {2} ir pradėkite iš naujo nuo {3} serijų po {4}.",
  "Stuck for {0} sessions. Back to {1} {2} of help, start again at {3} sets of {4}.": "Strigote {0} treniruotes. Grįžkite prie {1} {2} pagalbos, pradėkite iš naujo nuo {3} serijų po {4}.",
  "Sets from": "Serijos nuo",
  "Sets up to": "Serijos iki",
  "Exercises in this workout": "Šios treniruotės pratimai",
  "Exercise {0}: {1} ({2})": "Pratimas {0}: {1} ({2})",
  "Superset {0}: {1} ({2})": "Supersetas {0}: {1} ({2})",
