  "{0} APK, animations at {1} px": "{0} APK, animacijos {1} px raiška",
  "Download failed. Tap to try again.": "Atsisiuntimas nepavyko. Bandyti dar kartą.",
  "Download over Wi-Fi only": "Atsisiųsti tik per Wi-Fi",
  "Downloaded · {0}": "Atsisiųsta · {0}",
  "Downloading… {0}%": "Atsisiunčiama… {0}%",
  "No animation, just the picture. Easy on battery.": "Be animacijos, tik nuotrauka. Taupoma baterija.",
  "Not downloaded": "Neatsisiųsta",
  "On this device": "Šiame įrenginyje",
  "Sharper animations aren’t available on this device yet. The built-in ones work everywhere.": "Aštresnės animacijos šiam įrenginiui dar neprieinamos. Integruotosios veikia visur.",
  "Sharper animations download once per figure. Until they’re here you see the built-in ones, so nothing ever goes blank.": "Aštresnės animacijos atsisiunčiamos vieną kartą už kiekvieną figūrą. Kol jos atsisiųs, matysite integruotąsias, kad niekada niekur nebūtų tuščia.",
  "Still only": "Tik paveikslėlis",
  "Waiting for Wi-Fi": "Laukiama Wi-Fi",
  "{0} px": "{0} px",
  "Make the box bigger": "Padidinti langą",
  "Make the box smaller": "Sumažinti langą",
  "Photo removed": "Nuotrauka pašalinta",
  "A breather after one side, before the other. The full rest comes once both sides are done.": "Trumpa pertrauka po vienos pusės, prieš pradedant kitą. Pilnas poilsis suteikiamas, kai abi pusės atliktos.",
  "Like the work sets": "Toks pat kaip ir darbo serijoms",
  "No timer": "Be laikmačio",
  "Pick a time": "Pasirinkite laiką",
  "Rest between sides": "Poilsis tarp pusių",
  "Rest between warm-ups": "Poilsis tarp apšilimo serijų",
  "Warm-ups are light, so they can rest less, or not at all. The last one still gets the full rest before your first work set.": "Apšilimo serijos lengvos, todėl poilsio gali prireikti mažiau arba visai neprireikti. Paskutinė apšilimo serija vis tiek gauna pilną poilsį prieš pirmąją darbo seriją.",
  "Add photos": "Pridėti nuotraukų",
  "Each photo goes on the day it was taken.": "Kiekviena nuotrauka priskiriama dienai, kurią ji buvo padaryta.",
  "No progress photos yet. Add one for today or any day before.": "Kol kas nėra progreso nuotraukų. Pridėkite šios dienos arba bet kurios ankstesnės dienos nuotrauką.",
  "The photo says it was taken on {0}. Change the day if it was another one.": "Nuotraukoje nurodyta, kad ji padaryta {0}. Pakeiskite dieną, jei tai buvo kita data.",
  "They all go on the day below.": "Visos jos bus priskirtos žemiau nurodytai dienai.",
  "Which day is this photo from?": "Iš kurios dienos ši nuotrauka?",
  "Your server keeps photos only on days with a workout. An update lets it keep them for any day.": "Jūsų serveris saugo nuotraukas tik dienomis, kai buvo treniruotė. Atnaujinimas leidžia jas saugoti bet kurią dieną.",
