  "Every progress photo, lined up by date, for any day. Plus a before/after slider.": "Visos progreso nuotraukos sugrupuotos pagal datą, bet kuriai dienai. Pridėtas „prieš/po“ slankiklis.",
  "Add a backup": "Pridėti atsarginį pratimą",
  "Backups": "Atsarginės",
  "Backups for {0}": "Atsarginės {0}",
  "Everything else": "Viskas kita",
  "Machine taken? Pick what you’d do instead, and a swap mid-workout offers these first.": "Treniruoklis užimtas? Pasirinkite alternatyvą, o perjungus per treniruotę šie variantai bus pasiūlyti pirmiausia.",
  "Remove “{0}”": "Pašalinti „{0}“",
  "Rename “{0}”": "Pervadinti „{0}“",
  "That’s plenty of backups.": "Atsarginių pakanka.",
  "Your backups": "Jūsų atsarginės",
  "Swap to {0}": "Perjungti į {0}",
  "Planned backup, same sets and reps": "Suplanuotas atsarginis pratimas, tos pačios serijos ir pakartojimai",
  "Nothing to add in weight here: it goes up in reps, then sets.": "Čia svorio pridėti negalima: jis didinamas didinant pakartojimų skaičių, o vėliau – serijų.",
  "In Cards and Focus, Prev and Next hop over a finished exercise.": "Kortelėse ir Fokuse mygtukai „Ankstesnis“ ir „Kitas“ praleidžia baigtus pratimus.",
  "Skip completed exercises": "Praleisti baigtus pratimus",
  "This app can’t confirm with a passkey. Make the code in a browser signed in to this profile, or add a password there first.": "Ši programėlė negali patvirtinti naudojant prieigos raktą. Sukurkite kodą naršyklėje prisijungę prie šio profilio arba pirmiausia ten pridėkite slaptažodį.",
  "Apple Watch": "Apple Watch",
  "Weight": "Svoris",
  "Send workouts to the watch": "Siųsti treniruotes į laikrodį",
  "Open on the watch": "Atidaryti laikrodyje",
  "Start a workout on the phone and openGym pops up on your wrist.": "Pradėkite treniruotę telefone ir openGym atsidarys ant riešo.",
  "Not allowed": "Neleidžiama",
  "Turn on Apple Health and the watch measures your heart rate for every set.": "Įjunkite „Apple Health“, kad laikrodis matuotų jūsų širdies ritmą kiekvienos serijos metu.",
  "Tap the wrist when a rest is over": "Palieskite riešą, kai pasibaigs poilsis",
  "No Apple Watch paired with this iPhone": "Šis iPhone nesuporuotas su „Apple Watch“",
  "openGym is not on your Apple Watch yet. Install it in the Watch app.": "openGym dar nėra jūsų „Apple Watch“. Įdiekite jį per „Watch“ programėlę.",
  "openGym is on your Apple Watch": "openGym yra jūsų „Apple Watch“",
  "Last heard from the watch: {0}": "Paskutinį kartą gauta iš laikrodžio: {0}",
  "The watch hasn’t checked in yet. Open openGym on it once.": "Laikrodis dar nesusijungė. Vieną kartą atidarykite openGym ant laikrodžio.",
  "Not allowed on the watch. Allow it in the Health app on your iPhone.": "Laikrodyje neleidžiama. Leiskite prieigą „Health“ programėlėje telefone.",
  "Heart rate during the workout and next to each set, and the workout saved to Apple Health. The watch asks once.": "Širdies ritmas treniruotės metu ir šalia kiekvienos serijos, o treniruotė įrašoma į Apple Health. Laikrodis paklausia tik vieną kartą.",
  "Apple Health": "Apple Health",
  "Write to Apple Health": "Įrašyti į Apple Health",
  "Open Apple Health": "Atidaryti Apple Health",
  "Workouts and weigh-ins go to Apple Health when you finish or change them.": "Treniruotės ir svėrimai perduodami į „Apple Health“, kai juos baigiate arba pakeičiate.",
  "Writing to Apple Health": "Įrašoma į Apple Health",
  "Apple Health permission not granted": "Apple Health leidimas nesuteiktas",
  "Could not write to Apple Health": "Nepavyko įrašyti į Apple Health",
