  "Stop writing to Apple Health?": "Nustoti įrašyti į Apple Health?",
  "What openGym already wrote can stay in Apple Health as your data, or be removed from it.": "Ką openGym jau įrašė, gali likti Apple Health kaip jūsų duomenys arba būti iš jų pašalinti.",
  "Your workouts in Apple Health": "Jūsų treniruotės „Apple Health“",
  "openGym can save every workout and weigh-in to Apple Health, and your Apple Watch can show your heart rate while you lift.": "openGym gali įrašyti kiekvieną treniruotę ir svėrimą į Apple Health, o jūsų Apple Watch gali rodyti širdies ritmą kilnojant svorius.",
  "Workouts and weigh-ins saved to Apple Health": "Treniruotės ir svėrimai įrašyti į Apple Health",
  "Heart rate per set on your Apple Watch": "Širdies ritmas kiekvienos serijos metu jūsų „Apple Watch“",
  "Switch it off anytime in Settings": "Jį galite išjungti bet kada nustatymuose",
  "You can change it anytime in Settings.": "Jį galite pakeisti bet kada nustatymuose.",
