  "On the watch": "Laikrodyje",
  "Fewer things, bigger numbers. Pick what helps you mid-set.": "Mažiau informacijos, didesni skaitmenys. Pasirinkite, kas padės per seriją.",
  "Exercise animation": "Pratimo animacija",
