  "Countdown only": "Tik atgalinis skaičiavimas",
  "Progress bar": "Eigos juosta",
  "Watch rest screen: the countdown with a thin progress bar under it": "Laikrodžio poilsio ekranas: atgalinis skaičiavimas su plona eigos juosta po juo",
  "Watch rest screen: just the big countdown": "Laikrodžio poilsio ekranas: tik didelis atgalinis skaičiavimas",
  "Your bars": "Jūsų strypai",
  "Set the bar once for every exercise of a type.": "Nustatykite strypo svorį vieną kartą kiekvieno tipo pratimui.",
  "Your bar for this type, set in Your bars.": "Jūsų šio tipo strypas, nustatytas skiltyje „Jūsų strypai“.",
  "What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.": "Kiek sveria jūsų sporto salės strypai. Kiekvienas pratimas su tuo strypu automatiškai atskaičiuoja plokštelių svorį, nebent priskyrėte jam individualų strypą. Įvesti svoriai išlieka bendrais.",
  "Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.": "Dauguma pratimų bibliotekoje naudoja „{0}“, keli – „{1}“. Jei visiems naudosite trumpą strypą, reikės nustatyti abu.",
  "Back to the standard bars": "Grįžti prie standartinių strypų",
  "Standard bars. Tap if yours are lighter.": "Standartiniai strypai. Paspauskite, jei jūsų strypai sveria mažiau.",
  "The last warm-up still gets the full rest before your first work set.": "Paskutinė apšilimo serija vis tiek gauna pilną poilsį prieš pirmąją darbo seriją.",
  "Days per week": "Dienų per savaitę",
  "Hours": "Valandos",
  "h": "val.",
  "This device has 1 workout that is not in this backup. Replacing deletes it.": "Šiame įrenginyje yra 1 treniruotė, kurios nėra šioje atsarginėje kopijoje. Pakeitus, ji bus ištrinta.",
  "This device has {0} workouts that are not in this backup. Replacing deletes them.": "Šiame įrenginyje yra {0} treniruočių, kurių nėra šioje atsarginėje kopijoje. Pakeitus, jos bus ištrintos.",
  "Page {0} of {1}": "Puslapis {0} iš {1}",
