  "This lives in the openGym phone app.": "Tai yra „openGym“ telefono programėlėje.",
  "Your watch or scale writes here too? Garmin, COROS, Fitbit, Withings, Oura and friends reach openGym this way.": "Ar jūsų laikrodis ar svarstyklės taip pat siunčia duomenis čia? „Garmin“, „COROS“, „Fitbit“, „Withings“, „Oura“ ir kiti taip sinchronizuojasi su „openGym“.",
  "Now in Integrations": "Dabar „Integracijos“ skiltyje",
