  "One row per set, plus body weight and measurements.": "Po vieną eilutę kiekvienai serijai, taip pat kūno svoris ir matmenys.",
  "openGym can read it back in later.": "„openGym“ tai galės perskaityti vėliau.",
  "Tell Home Assistant, n8n or ntfy when you finish a workout.": "Praneškite „Home Assistant“, n8n arba ntfy, kai baigsite treniruotę.",
  "A signed JSON message when a workout is finished, a record falls or you weigh in.": "Pasirašytas JSON pranešimas, kai baigiama treniruotė, nugalėtas rekordas arba atliekamas svorio matavimas.",
