  "An exercise’s history, records and progress are worked out from your workouts. Fix the workout and they follow.": "Pratimo istorija, rekordai ir progresas skaičiuojami iš jūsų treniruočių. Sutvarkykite treniruotę, ir jie atnaujins.",
