  "When the rest ends: 3, 2, 1 and the hold starts. Pause, restart or stop it any time.": "Pasibaigus poilsio laikui: 3, 2, 1 ir prasideda laikymas. Bet kada galite pristabdyti, paleisti iš naujo arba sustabdyti.",
  "Holds start by themselves": "Laikymai prasideda patys",
  "Add {0}?": "Pridėti {0}?",
  "Any blank NTAG sticker works. Writing replaces what was on it.": "Tinka bet koks tuščias NTAG lipdukas. Rašymas perrašys tai, kas buvo ant jo.",
  "Hold the back of your phone to the sticker.": "Prispauskite telefono galinę dalį prie lipduko.",
  "Hold the top of your iPhone near the sticker.": "Prispauskite iPhone viršutinę dalį prie lipduko.",
  "It isn’t in this workout yet.": "Šioje treniruotėje jo dar nėra.",
  "Just check in": "Tiesiog pažymėti atvykimą",
  "NFC is off. Turn it on in your phone’s settings and try again.": "NFC išjungtas. Įjunkite jį telefono nustatymuose ir bandykite dar kartą.",
  "NFC sticker for this exercise": "Šio pratimo NFC lipdukas",
  "Put it on your locker, your bag or the gym door. One tap with your phone and you’re in.": "Uždėkite ant spintelės, maišo arba sporto salės durų. Prisilietus telefonu – ir jūs viduje.",
  "Set up an NFC sticker": "Nustatyti NFC lipduką",
  "Shows your gym membership code, ready for the scanner.": "Rodo jūsų sporto salės narystės kodą, paruoštą nuskaitymui.",
  "Start today’s workout": "Pradėti šiandienos treniruotę",
  "Starts what’s planned for today, or opens the one already running.": "Paleidžia šiandienos programą arba atidaro jau vykstančią treniruotę.",
  "Stick it on the machine. Tap it during a workout to jump to {0}, or to add it.": "Uždėkite ant treniruoklio. Treniruotės metu prisilieskite prie jo, kad peršoktumėte į {0} arba jį pridėtumėte.",
  "Sticker ready.": "Lipdukas paruoštas.",
  "Sticker ready. Tap it with your phone to try it.": "Lipdukas paruoštas. Prisilieskite prie jo telefonu, kad išbandytumėte.",
  "Tap it at the gym to start your workout or show your code.": "Prisilieskite prie jo sporto salėje, kad pradėtumėte treniruotę arba parodytumėte kodą.",
  "That didn’t work. Hold your phone still on the sticker and try again.": "Nepavyko. Laikykite telefoną nejudant ant lipduko ir bandykite dar kartą.",
  "This sticker can’t hold a link. Try an NTAG sticker.": "Šis lipdukas negali saugoti nuorodos. Pabandykite NTAG lipduką.",
  "This sticker is for an exercise you don’t have.": "Šis lipdukas skirtas pratimui, kurio neturite.",
  "This sticker is locked. Try a blank one.": "Šis lipdukas užrakintas. Pabandykite tuščią.",
  "This sticker is too small. NTAG213 or bigger works.": "Šis lipdukas per mažas. Tinka NTAG213 arba didesnis.",
  "When you tap it": "Kai prie jo prisilietiate",
  "Which code": "Kurį kodą",
  "Write NFC sticker for this exercise": "Įrašyti NFC lipduką šiam pratimui",
  "Write sticker": "Įrašyti lipduką",
  "openGym isn’t allowed to use NFC here.": "„openGym“ čia neturi leidimo naudoti NFC.",
