  "One more week with a workout earns a freeze.": "Dar viena savaitė su treniruote suteiks vieną tęstinumo apsaugą.",
  "{0} more weeks with a workout earn a freeze.": {"one": "{0} savaitė su treniruote leis sustabdyti stebėjimą", "few": "{0} savaitės su treniruotėmis leis sustabdyti stebėjimą", "many": "Dar {0} savaitės su treniruote suteiks vieną tęstinumo apsaugą.", "other": "{0} savaičių su treniruotėmis leis sustabdyti stebėjimą"},
