  "Opens a search for good form": "Atidaro paiešką dėl teisingos technikos",
  "Share with a friend": "Dalintis su draugu",
  "As a routine they can do too": "Kaip programą jie taip pat gali atlikti",
  "Nothing to share in this one.": "Šioje programoje bendrinti nieko negalima.",
  "Link copied. Paste it to a friend.": "Nuoroda nukopijuota. Įklijuokite ją draugui.",
  "That one’s too big for a link, so it goes as a plan file.": "Ji per didelė nuorodai, todėl bus išsiųsta kaip plano failas.",
  "Here’s my {0} on openGym 💪": "Štai mano {0} „openGym“ 💪",
  "Couldn’t make a link for this one.": "Nepavyko sukurti nuorodos.",
  "A link to “{0}”. Your friend taps it and adds it to their own openGym. The routine rides inside the link, no server in between.": "Nuoroda į „{0}“. Draugas ją paspaudžia ir prideda prie savo „openGym“. Programa įterpta į nuorodą, be serverio tarpininko.",
  "Include my weights": "Įtraukti mano svorius",
  "Off: just sets, reps and rest. They pick their own weights.": "Išjungta: tik serijos, pakartojimai ir poilsis. Kiti pasirenka savo svorius.",
  "So they know who it’s from.": "Kad žinotų, nuo kieno.",
  "Share link": "Dalintis nuoroda",
  "From {0}": "Nuo {0}",
  "Added as a new routine. Nothing you already have is touched.": "Pridėta kaip nauja programa. Jūsų turimos programos nepaliestos.",
  "Add to my routines": "Pridėti prie mano programų",
  "Added to your routines": "Pridėta prie jūsų programų",
  "This link is from a newer openGym. Update the app to open it.": "Ši nuoroda iš naujesnės „openGym“ versijos. Atnaujinkite programėlę, kad ją atidarytumėte.",
  "This browser can’t open this link. Try it in the openGym app.": "Ši naršyklė negali atidaryti šios nuorodos. Pabandykite „openGym“ programėlėje.",
  "Nothing in this routine works here, sorry.": "Šioje programoje čia nieko neveikia, atsiprašome.",
  "This routine link is broken or cut off.": "Ši programos nuoroda sugedusi arba pertrūkiusi.",
  "(from {0})": "(nuo {0})",
  "Mostly in the morning. The early bird gets the barbell.": "Dažniausiai ryte. Ankstyvas paukštis gauna štangą.",
  "Mostly around lunch. Who needs a lunch break anyway?": "Dažniausiai apie pietus. Kam vis tiek reikia pietų pertraukos?",
  "Mostly in the afternoon. The sweet spot.": "Dažniausiai popiet. Geriausias laikas.",
  "Mostly in the evening. Work, then work out.": "Dažniausiai vakare. Darbas, tada treniruotė.",
  "Mostly late at night. The gym is all yours.": "Dažniausiai vėlai naktį. Sporto salė tik jums.",
  "Early bird": "Ankstyvas paukštis",
  "Most of your sessions started before 9. The sun was still catching up.": "Dauguma jūsų treniruočių prasidėjo prieš 9. Saulė dar tik kėlėsi.",
  "Night owl": "Naktinis gyventojas",
  "Most of your sessions started after 8 pm. The quiet gym is your gym.": "Dauguma jūsų treniruočių prasidėjo po 20 val. Tyli sporto salė yra jūsų.",
  "Leg-day loyalist": "Kojų dienų šalininkas",
  "You never skipped leg day. Stairs fear you.": "Niekada nepraleidote kojų dienos. Laiptai jūsų bijo.",
  "Clockwork": "Taisyklingas ritmas",
  "Week after week after week. Your calendar knows your name.": "Savaitė po savaitės. Jūsų kalendorius puikiai jus pažįsta.",
  "Record breaker": "Rekordų griovėjas",
  "So many new bests, your trophy shelf needs a trophy shelf.": "Tiek daug naujų geriausių rezultatų, kad trofėjų lentynai jau reikia papildomos lentynos.",
  "Weekend warrior": "Savaitgalio kovotojas",
  "Saturdays and Sundays are for lifting. Brunch can wait.": "Šeštadieniai ir sekmadieniai skirti kėlimui. Brunchas gali palaukti.",
  "Cardio comet": "Kardiokometas",
  "Your heart is in great shape. Literally.": "Jūsų širdis puikios formos. Būtent taip.",
  "In it for the long haul": "Atkaklusis",
  "Long sessions, no rush. The gym is basically your second home.": "Ilgos treniruotės, skubėti nereikia. Sporto salė yra jūsų antrieji namai.",
  "In and out": "Į ir iš",
  "Short, sharp sessions. Efficiency is your love language.": "Trumpos, intensyvios treniruotės. Efektyvumas yra jūsų meilės kalba.",
  "Explorer": "Tyrinėtojas",
  "So many different exercises, boredom never stood a chance.": "Tiek daug skirtingų pratimų – nuobodulys neturėjo nė menkiausios galimybės.",
