  "Follows Settings → Workout → Automatic warm-ups.": "Naudojamas pasirinkimas Nustatymai → Treniruotė → Automatinės apšilimo serijos.",
  "For this workout": "Šiai treniruotei",
  "Heavy lifts get more rungs, light ones one or none.": "Sunkiems pratimams pridedama daugiau apšilimo serijų, lengviems – viena arba nė vienos.",
  "It hurts": "Skauda",
  "It hurts, it’s taken, no time, feeling great": "Skauda, užimta, nėra laiko, jaučiuosi puikiai",
  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "Jaučiamas spaudimas, todėl likusiems pakartojimams sumažinkite svorį. Jei skausmas išlieka, sustokite.",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "Jaučiamas diskomfortas, todėl likusias serijas pakeiskite pratimu, kuris ta pačią raumenų grupę apkrauna švelnesniu kampu.",
  "Keep these warm-ups": "Išsaugoti šias apšilimo serijas",
  "Kept. Same warm-ups next time, scaled to your work weight.": "Išsaugota. Kitą kartą bus naudojamos tos pačios apšilimo serijos, pritaikytos prie darbinio svorio.",
  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "Užregistruotos serijos ir jūsų programa lieka nepakitusios. Treneris nėra gydytojas ar fizioterapeutas. Jei skauda, kreipkitės į specialistą.",
  "Looking at your workout…": "Analizuojama jūsų treniruotė…",
  "Machine’s taken": "Treniruoklis užimtas",
  "My own": "Mano",
  "New programme “{0}”": "Naujas treniruočių planas „{0}“",
  "Nothing at {0} {1}: that one starts cold.": "Esant {0} {1}, apšilimo serijų nėra.",
  "Nothing could be applied any more.": "Nėra ko daugiau pakeisti.",
  "Nothing to change. Carry on as planned.": "Nėra ką keisti. Tęskite pagal planą.",
  "One set less keeps the session doable today and still counts.": "Viena serija mažiau padaro šiandienos sesiją įmanomą ir vis tiek skaičiuojama.",
  "Only the warm-ups you plan yourself.": "Tik pačių suplanuotos apšilimo serijos.",
  "Ramped from the work weight: more rungs when it is heavy, fewer when it is light.": "Palaipsnis svorio didinimas nuo darbo svorio: daugiau laiptelių, kai svoris didelis, mažiau – kai mažas.",
  "Remove warm-up {0}": "Pašalinti apšilimo seriją {0}",
  "Revise programme “{0}”": "Patikslinti treniruočių planą „{0}“",
  "Routines, exercises, sets and reps, warm-ups, programmes, your weekly schedule, progression settings and what your gym can load.": "Programos, pratimai, serijos ir pakartojimai, apšilimo serijos, treniruočių planai, savaitės tvarkaraštis, progresavimo nustatymai ir sporto salėje turima įranga.",
  "Running on empty": "Trūksta energijos",
  "Saved in the routine, scaled to your work weight": "Išsaugota programoje, pritaikyta prie jūsų darbo svorio",
  "Saved under Plan → Programmes. It starts when you start it.": "Išsaugota skiltyje Planas → Treniruočių planai. Jis prasideda, kai patys jį paleidžiate.",
  "Short on time": "Trūksta laiko",
  "Skip the rest of {0}": "Praleisti likusią {0}",
  "Something else": "Kažkas kita",
  "Squats, presses, rows and friends get a ramp. Curls and raises start cold.": "Pritūpimams, spaudimams, traukoms ir kitiems sudėtiniams pratimams pridedamos laipsniškos apšilimo serijos. Rankų lenkimai ir kėlimai pradedami be jų.",
  "Straight into the work sets.": "Tiesiogiai pereinama prie darbo serijų.",
  "That workout is over, so these can’t be applied any more.": "Ši treniruotė baigta, todėl šių jau nebegalima taikyti.",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "Programėlė parenka didėjančias apšilimo serijas pagal darbinį svorį: daugiau, kai svoris didelis, mažiau, kai lengvas, ir suapvalina pagal sporto salėje turimus diskus.",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "Stovas užimtas, todėl atlikite pratimą pabaigoje. Likusiai sesijos daliai jis nereikalingas.",
  "There’s no workout running.": "Šiuo metu nevyksta jokia treniruotė.",
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": "Šios apšilimo serijos atliekamos prieš darbo serijas ir sudaro dalį darbinio svorio, todėl didėja kartu su juo.",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "Tai demonstracinė versija, todėl už manęs nėra AI modelio. Jūsų serveryje aš skaitau jūsų sesiją ir siūlau tokius pakeitimus.",
  "Warm-up {0}": "Apšilimo serija {0}",
  "Warm-ups": "Apšilimo serijos",
  "What’s up? The Coach suggests a few changes to what is left of this workout. Logged sets stay as they are.": "Kaip sekasi? Treneris siūlo keletą pakeitimų likusiai šios treniruotės daliai. Įrašytos serijos lieka nepakitusios.",
  "Where, and what movement hurts? (optional)": "Kur ir kuris judesys skauda? (neprivaloma)",
  "With {0} {1} today: {2}": "Šiandien su {0} {1}: {2}",
  "You can keep training, the answer waits here and in the Coach.": "Galite toliau treniruotis, atsakymas laukia čia ir Trenerio programoje.",
  "You feel strong, so a little more on the bar for what is left. Not a new max, just a nudge.": "Jaučiatės stiprūs, todėl likusiems pakartojimams šiek tiek padidinsime svorį ant strypo. Tai ne naujas maksimumas, o tik nedidelis paskatinimas.",
  "Your rows, as a share of the work weight, so they grow with it.": "Jūsų įvestos eilutės sudaro dalį darbinio svorio, todėl didėja kartu su juo.",
  "Your workout moved on, so this one no longer fits.": "Jūsų treniruotė pažengė toliau, todėl ši nebeaktuali.",
