  "Amazfit and other Zepp OS watches talk to openGym through this server. Pair one and your workouts show up on your wrist.": "Amazfit ir kiti Zepp OS laikrodžiai su „openGym“ bendrauja per šį serverį. Susiekite laikrodį, kad treniruotės būtų matomos ant riešo.",
