  "Weigh-ins, measurements, progress photos and your weight goal.": "Svorio matavimai, apimčių matavimai, progreso nuotraukos ir jūsų svorio tikslas.",
  "Your membership codes on Home, and NFC stickers that start a workout.": "Jūsų narystės kodai „Home“ ekrane bei NFC lipdukai, kurie paleidžia treniruotę.",
  "Your own mix. Flip the switches below.": "Jūsų asmeninis derinys. Perjunkite žemiau esančius jungiklius.",
  "Your watch stops getting workouts while Watch is off. It stays paired.": "Jūsų laikrodis nustos gauti treniruotes, kol „Watch“ išjungtas. Jis išlieka suporuotas.",
  "Your webhooks stop sending while Integrations is off. They stay set up.": "Jūsų webhook'ai nustos siųsti, kol „Integrations“ išjungtas. Jie išlieka sukonfigūruoti.",
  "{0} of {1} modules on.": "Įjungta {0} iš {1} modulių.",
  "{0} stops syncing while Health is off. Nothing is disconnected, and it catches up once Health is back.": "„{0}“ nustos sinchronizuoti, kol „Health“ išjungtas. Nieko neatsijungia, o sinchronizavimas atsistatys, kai „Health“ vėl įsijungs.",
  "Not in \"{0}\": {1} more": "Nėra „{0}“: dar {1}",
  "Added before your work sets and left out of volume, records and progression. On an assistance machine each one has more help than the work set, stepping down toward it, and you can still change any of them mid-session.": "Pridedami prieš darbines serijas ir neįskaičiuojami į apimtį, rekordus ir progresą. Ant pagalbinio treniruoklio kiekviena turi daugiau pagalbos nei darbinė serija ir pamažu artėja prie jos. Bet kurią vis tiek galite pakeisti treniruotės metu.",
  "The Coach hit its AI provider’s limit. Try again later, or the instance owner needs to check the plan or key.": "Treneris pasiekė savo DI tiekėjo limitą. Bandykite vėliau arba serverio savininkas turi patikrinti planą ar raktą.",
  "The Coach’s AI provider rejected the request format. The instance owner needs to try another model.": "Trenerio DI tiekėjas atmetė užklausos formatą. Serverio savininkas turi išbandyti kitą modelį.",
  "The Coach’s AI provider is having an outage. Try again in a little while.": "Trenerio DI tiekėjas šiuo metu neveikia. Pabandykite po kurio laiko.",
  "The Coach couldn’t reach its AI provider. The instance owner needs to check the endpoint and the network.": "Treneris nepasiekė savo DI tiekėjo. Serverio savininkas turi patikrinti adresą ir tinklą.",
  "Lengths in": "Ilgiai",
  "Removes the field and every reading logged in it. The other measurements stay.": "Pašalina lauką ir visus jame įrašytus matavimus. Kiti matmenys lieka.",
  "Sharper animations come only through the app stores. This APK keeps the ones built into it.": "Ryškesnės animacijos pasiekiamos tik per programėlių parduotuves. Šis APK naudoja į jį įdėtas.",
  "Planned backup, with its own plan": "Suplanuota atsarginė, su savo planu",
  "Same plan as this exercise. Tap to give it its own.": "Toks pat planas kaip šio pratimo. Bakstelėkite, kad suteiktumėte atskirą.",
  "Added before your work sets. They count in your volume (Settings), but stay out of records and progression. On an assistance machine each one has more help than the work set, stepping down toward it, and you can still change any of them mid-session.": "Pridedami prieš darbines serijas. Įskaičiuojami į apimtį (Nustatymai), bet ne į rekordus ir progresą. Ant pagalbinio treniruoklio kiekviena turi daugiau pagalbos nei darbinė serija ir pamažu artėja prie jos. Bet kurią vis tiek galite pakeisti treniruotės metu.",
  "Screen orientation": "Ekrano padėtis",
  "Only for openGym. Your phone’s auto-rotate stays as it is.": "Tik openGym. Telefono automatinis pasukimas lieka kaip buvo.",
