  "This sound cannot be read here. Try an MP3, M4A, WAV or OGG file.": "Šio garso čia nepavyksta nuskaityti. Pabandykite MP3, M4A, WAV arba OGG failą.",
  "Up to 30 seconds, from an MP3, M4A, WAV or OGG file. Silence at either end is trimmed off.": "Iki 30 sekundžių iš MP3, M4A, WAV arba OGG failo. Tyla pradžioje ir pabaigoje nukerpama.",
  "Your own sounds": "Jūsų garsai",
  "openGym isn’t in the Zepp App Store yet. Until it is, the watch app goes on through the Zepp app’s developer mode. The guide walks you through it.": "openGym dar nėra Zepp App Store. Kol kas laikrodžio programėlė diegiama per Zepp programėlės kūrėjo režimą. Vadovas viską paaiškins.",
  "Install the watch app": "Įdiegti laikrodžio programėlę",
  "A Zepp OS watch reaches openGym through your own openGym server, since its side of the app runs inside the Zepp app and not here. Connect this phone to your server and the pairing code shows up right here.": "Zepp OS laikrodis pasiekia openGym per jūsų openGym serverį, nes jo programėlės dalis veikia Zepp programėlėje, o ne čia. Prijunkite šį telefoną prie serverio ir susiejimo kodas pasirodys čia.",
