  "Miss a week and a freeze covers it: the streak keeps going, that week just adds nothing. No freeze left, and it starts over.": "Praleidus savaitę ją padengia užšaldymas: serija tęsiasi, tik ta savaitė nieko neprideda. Neliko užšaldymų, ir serija prasideda iš naujo.",
