  "Photo crop. Arrow keys move it, plus and minus zoom.": "Nuotraukos apkirpimas. Rodyklės perkelia, plius ir minus priartina.",
  "Picture removed. Back to the letter.": "Nuotrauka pašalinta. Vėl raidė.",
  "Picture set. Looking sharp.": "Nuotrauka nustatyta. Atrodote puikiai.",
  "Profile picture": "Profilio nuotrauka",
  "Remove picture": "Pašalinti nuotrauką",
  "That isn’t a photo. Try a JPEG, PNG, WebP or HEIC.": "Tai ne nuotrauka. Pabandykite JPEG, PNG, WebP arba HEIC.",
  "Use this photo": "Naudoti šią nuotrauką",
  "Zoom": "Mastelis",
  "Missed plan": "Praleistas planas",
  "Open this day": "Atidaryti šią dieną",
  "Planned, not trained. Any other day this week still counts.": "Suplanuota, bet nesitreniruota. Bet kuri kita šios savaitės diena vis dar skaičiuojasi.",
  "Planned, not trained. Any workout that week would have counted.": "Suplanuota, bet nesitreniruota. Būtų įskaityta bet kuri tos savaitės treniruotė.",
  "Planned, not trained. No harm done: you trained another day that week, so it still counts.": "Suplanuota, bet nesitreniruota. Nieko tokio: tą savaitę treniravotės kitą dieną, todėl ji vis tiek įskaityta.",
  "Bank 1 freeze, earned every 4 trained weeks. Two missed weeks in a row end the streak.": "Sukaupkite 1 užšaldymą, uždirbamą kas 4 treniruočių savaites. Dvi praleistos savaitės iš eilės baigia seriją.",
  "Bank up to 2 freezes, one every 4 trained weeks. Even two missed weeks in a row can be covered.": "Sukaupkite iki 2 užšaldymų, po vieną kas 4 treniruočių savaites. Galima padengti net dvi praleistas savaites iš eilės.",
  "Change the freeze rule": "Keisti užšaldymo taisyklę",
  "Every 4th week you train earns a freeze. You can bank 1.": "Kas 4-a treniruočių savaitė suteikia užšaldymą. Galite sukaupti 1.",
  "Every week counts. Miss one and the streak starts over.": "Skaičiuojasi kiekviena savaitė. Praleidus vieną serija prasideda iš naujo.",
  "From now on: {0}.": "Nuo dabar: {0}.",
  "From the week of {0} on: {1}.": "Nuo {0} savaitės: {1}.",
  "Generous": "Dosni",
  "Gentle": "Švelni",
  "How forgiving should your week streak be?": "Kiek atlaidi turėtų būti jūsų savaičių serija?",
  "How strict should your streak be?": "Kiek griežta turėtų būti jūsų serija?",
  "Miss a week and a freeze covers it: the streak keeps going, that week just adds nothing. Two missed weeks in a row, and it starts over.": "Praleidus savaitę ją padengia užšaldymas: serija tęsiasi, tik ta savaitė nieko neprideda. Dvi praleistos savaitės iš eilės, ir serija prasideda iš naujo.",
  "No freezes": "Be užšaldymų",
  "No freezes on your rule. Every week counts.": "Jūsų taisyklėje užšaldymų nėra. Skaičiuojasi kiekviena savaitė.",
  "No freezes on your rule: a week without a workout starts it over.": "Jūsų taisyklėje užšaldymų nėra: savaitė be treniruotės pradeda seriją iš naujo.",
  "No workout, and your rule has no freezes, so the streak started over.": "Treniruotės nebuvo, o jūsų taisyklėje užšaldymų nėra, todėl serija prasidėjo iš naujo.",
  "Weeks already counted stay as they are.": "Jau įskaitytos savaitės lieka kaip buvo.",
  "You can change it later in Settings. A change counts from then on.": "Vėliau galėsite pakeisti nustatymuose. Pakeitimas galios nuo tada.",
  "Your rule right now: {0}.": "Jūsų dabartinė taisyklė: {0}.",
