  "{0} sees only what is on here.": "{0} mato tik tai, kas čia įjungta.",
  "You are letting this trainer see the categories marked here, and change the ones marked suggest or apply. If the trainer works for a gym, its gym lead sees the categories in the gym lead row, never more than view. You can change this or disconnect any time, and it stops working the moment you do. Every look and every change is written to your sharing log, which only you can read.": "Leidžiate šiam treneriui matyti čia pažymėtas kategorijas ir keisti tas, kurios pažymėtos kaip siūlymas ar keitimas. Jei treneris dirba sporto salėje, jos vadovas mato kategorijas vadovo eilutėje, bet tik peržiūrai. Tai galite bet kada pakeisti arba atsijungti, ir tai nustoja veikti tą pačią akimirką. Kiekviena peržiūra ir kiekvienas pakeitimas įrašomi į jūsų bendrinimo žurnalą, kurį skaityti galite tik jūs.",
