  "They scan it or type it in Trainer & gym, pick what to share, and you confirm. Nothing moves before that.": "Jie jį nuskenuoja arba įveda skiltyje „Treneris ir sporto salė“, pasirenka, kuo dalintis, o jūs patvirtinate. Iki tol niekas nevyksta.",
