  "The sharing text changed. Have a quick read and try again.": "Bendrinimo tekstas pasikeitė. Greitai perskaitykite ir bandykite dar kartą.",
  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "Tai vieša visiems šio serverio naudotojams: kiekvienas, turintis čia paskyrą, gali tai matyti, išbandyti ir nukopijuoti. Jūsų vardas ir data visada pridedami. Dalinkitės tik tuo, kas jūsų: ką sukūrėte, įrašėte ar turite teisę perduoti. Įtaisytos bibliotekos pratimų paveikslėliai ir animacijos yra licencijuoti, jais dalintis negalima. Nebesidalinti galite bet kada; jau paimtos kopijos lieka žmonėms.",
