  "Slider": "Slankiklis",
  "Still loading the photos. Try again in a second.": "Nuotraukos dar kraunasi. Pabandyk po sekundės.",
  "Switch camera": "Perjungti kamerą",
  "The camera is switched off for openGym. Allow it in your settings, or use the camera app instead.": "Kamera openGym išjungta. Leisk ją nustatymuose arba naudok kameros programą.",
  "The photo you just took": "Ką tik padaryta nuotrauka",
