  "No incline or decline work in the library or the Coach’s picks.": "Jokių pratimų ant pakelto ar nuleisto suolo bibliotekoje ir Trenerio pasiūlymuose.",
  "Bench work stays out of the library until you get one.": "Pratimai ant suolo lieka už bibliotekos ribų, kol jo neturi.",
  "Everything, flat bench only": "Viskas, tik plokščias suolas",
