  "Only you see it. It travels with your account.": "Matai tik tu. Jis keliauja su tavo paskyra.",
  "Show how you do it, on your own machine. Only you see it.": "Parodyk, kaip darai tu, ant savo treniruoklio. Matai tik tu.",
