  "Two happy notes after the tick, when sounds are on.": "Dvi linksmos natos po pažymėjimo, kai garsai įjungti.",
  "Type a time like 25:00 or 1:45:00.": "Įvesk laiką, pvz. 25:00 arba 1:45:00.",
  "U.S. Navy tape method. Waist at the navel, neck below the larynx.": "JAV karinio laivyno matavimo juosta. Juosmuo ties bamba, kaklas po gerklomis.",
  "Under the next set: its share of your best e1RM and the reps a record needs.": "Po kita serija: jos dalis nuo geriausio e1RM ir kiek pakartojimų reikia rekordui.",
