  "{0} more reps for a record at this weight": {"one": "Dar {0} pakartojimas iki rekordo su šiuo svoriu", "few": "Dar {0} pakartojimai iki rekordo su šiuo svoriu", "many": "Dar {0} pakartojimo iki rekordo su šiuo svoriu", "other": "Dar {0} pakartojimų iki rekordo su šiuo svoriu"},
  // --- Settings → Garmin (garmin-146) ---
  "This version of openGym comes without the Garmin link, since Garmin’s part of it isn’t open source. The App Store, Google Play and GitHub versions have it.": "Šioje openGym versijoje nėra Garmin ryšio, nes Garmin dalis nėra atvirojo kodo. App Store, Google Play ir GitHub versijose jis yra.",
  "Garmin Connect isn’t on this phone. Install it, pair your watch there, then come back here.": "Šiame telefone nėra Garmin Connect. Įdiek jį, ten susiek laikrodį ir grįžk čia.",
  "Garmin Connect needs an update before openGym can talk to your watch.": "Garmin Connect reikia atnaujinti, kad openGym galėtų kalbėtis su tavo laikrodžiu.",
  "Couldn’t reach Garmin Connect. Try again in a moment.": "Nepavyko pasiekti Garmin Connect. Pabandyk po akimirkos.",
  "Pick your Garmin in Garmin Connect and your workouts show up on your wrist.": "Pasirink savo Garmin programėlėje Garmin Connect ir treniruotės atsiras ant riešo.",
  "Your Garmin isn’t in reach right now. Bring it close with Bluetooth on, and this page catches up by itself.": "Tavo Garmin dabar nepasiekiamas. Priartink jį su įjungtu Bluetooth, ir šis puslapis atsinaujins pats.",
  "Garmin Connect doesn’t know a watch yet. Pair yours there first.": "Garmin Connect dar nežino jokio laikrodžio. Pirmiausia ten susiek savąjį.",
  "openGym is on your Garmin. Sets you log on the wrist land here.": "openGym yra tavo Garmin. Ant riešo užrašyti priėjimai atkeliauja čia.",
  "openGym is on your Garmin. It catches up as soon as the watch is in reach.": "openGym yra tavo Garmin. Viską pasivys, kai tik laikrodis bus pasiekiamas.",
  "Your Garmin is here, openGym isn’t on it yet. Get it, then open it once on the watch.": "Tavo Garmin čia, bet openGym jame dar nėra. Įsidiek ir kartą atidaryk laikrodyje.",
  "Not in reach": "Nepasiekiamas",
  "openGym isn’t on it yet": "openGym jame dar nėra",
  "Your Garmins": "Tavo Garmin",
  "Choose watches": "Pasirinkti laikrodžius",
  "Look again": "Ieškoti dar kartą",
  "Get openGym for Garmin": "Gauti openGym Garmin laikrodžiui",
  "Start a workout on the phone and your Garmin asks to open openGym.": "Pradėk treniruotę telefone ir Garmin paklaus, ar atidaryti openGym.",
  // --- daily form, vitals, month story (gm-insights-146) ---
  "10% lighter": "10 % lengviau",
  "About the same": "Maždaug tas pats",
  "After 7 hours of sleep or more": "Po 7 ar daugiau valandų miego",
  "As planned": "Kaip suplanuota",
  "Barely slept": "Beveik nemiegojau",
  "Calm": "Ramu",
  "Check in before workouts?": "Pasižymėti prieš treniruotę?",
  "Could easily be chance": "Gali būti ir atsitiktinumas",
  "Daily check-in": "Kasdienis pasižymėjimas",
  "Daily form": "Dienos forma",
  "Energy": "Energija",
  "Estimated strength": "Apskaičiuota jėga",
  "Every single week. That is a habit, not a phase.": "Kiekvieną savaitę be išimties. Tai įprotis, ne etapas.",
  "Every week you showed up counted.": "Kiekviena savaitė, kai atėjai, buvo įskaityta.",
  "Everything aches": "Skauda viską",
  "Exercise of the month": "Mėnesio pratimas",
  "For the Daily form card in Stats and your check-in. Read on this phone only, never sent anywhere.": "Dienos formos kortelei Statistikoje ir tavo pasižymėjimui. Skaitoma tik šiame telefone, niekur nesiunčiama.",
  "Four taps on sleep, energy, soreness and stress. On a rough day openGym offers to go lighter, and after a few weeks you see what your good days have in common.": "Keturi palietimai apie miegą, energiją, raumenų skausmą ir stresą. Sunkią dieną openGym pasiūlys lengvesnę treniruotę, o po kelių savaičių pamatysi, kas bendra tavo geroms dienoms.",
  "Frazzled": "Ant nervų",
  "From Apple Health, read-only, on this phone only.": "Iš Apple Health, tik skaitymas, tik šiame telefone.",
  "From Health Connect, read-only, on this phone only.": "Iš Health Connect, tik skaitymas, tik šiame telefone.",
  "Full of beans": "Pilnas jėgų",
  "HRV (RMSSD)": "ŠRV (RMSSD)",
  "HRV (SDNN)": "ŠRV (SDNN)",
  "How are you today?": "Kaip šiandien jautiesi?",
  "How your days and your workouts line up": "Kaip tavo dienos ir treniruotės susijusios",
  "Insights show up once there is enough to compare: {0} of {1} workouts so far.": "Įžvalgos atsiras, kai bus pakankamai ką palyginti: kol kas {0} iš {1} treniruočių.",
  "Just today. This session sits out of progression, so your next targets stay put.": "Tik šiandien. Ši treniruotė neįskaitoma į progresiją, tad kiti tikslai lieka vietoje.",
  "Leaning that way": "Krypsta ta linkme",
  "Lighter day: 10% off the weights. Progression sits this one out.": "Lengvesnė diena: 10 % mažesnis svoris. Progresija šįkart praleidžia.",
  "Lighter day: one set fewer per exercise. Progression sits this one out.": "Lengvesnė diena: vienu serija mažiau kiekvienam pratimui. Progresija šįkart praleidžia.",
  "More than last month. Momentum looks good on you.": "Daugiau nei praėjusį mėnesį. Įsibėgėjimas tau tinka.",
  "New moves, new muscles asking questions. Curiosity pays.": "Nauji judesiai, nauji raumenys su klausimais. Smalsumas atsiperka.",
  "Not a single week off. Your calendar is impressed.": "Nė vienos savaitės pertraukos. Tavo kalendorius sužavėtas.",
  "Not for me": "Ne man",
  "Nothing aches": "Niekas neskauda",
  "On your good-form days": "Tavo geros formos dienomis",
  "One month, the short version.": "Vienas mėnuo, trumpai.",
  "One set fewer": "Viena serija mažiau",
  "Patterns, not proof. Sleep is rarely the only thing that changed that day.": "Dėsningumai, ne įrodymai. Miegas retai yra vienintelis dalykas, kuris tą dieną pasikeitė.",
  "Play your month": "Peržiūrėti savo mėnesį",
  "Pretty consistent so far": "Kol kas gana pastovu",
  "Read your vitals?": "Skaityti tavo gyvybinius rodiklius?",
  "Reps in reserve": "Pakartojimai atsargoje",
  "Resting heart rate": "Ramybės pulsas",
  "Rough one. Take it easier today?": "Sunki diena. Šiandien lengviau?",
  "Running on fumes": "Ant paskutinių atsargų",
  "Same as {0}. Steady wins.": "Kaip {0}. Pastovumas laimi.",
  "Share my month": "Dalintis savo mėnesiu",
  "Showing up is the whole trick, and you did it.": "Visa gudrybė yra ateiti, ir tu tai padarei.",
  "Skip for today": "Praleisti šiandien",
  "Sleep": "Miegas",
  "Sleep, energy, soreness and stress in four taps before you train. On a rough day it offers to go lighter.": "Miegas, energija, raumenų skausmas ir stresas keturiais palietimais prieš treniruotę. Sunkią dieną pasiūlo lengvesnę.",
  "Sleep, resting heart rate, HRV and steps": "Miegas, ramybės pulsas, ŠRV ir žingsniai",
  "Slept like a log": "Miegojau kaip užmuštas",
  "So far your good and rough days end in about the same workouts. Nice and steady.": "Kol kas tavo geros ir sunkios dienos baigiasi panašiomis treniruotėmis. Gražiai tolygu.",
  "So many records, the plates are filing a complaint.": "Tiek rekordų, kad svoriai pateikė skundą.",
