  "Steps": "Žingsniai",
  "Steps today": "Žingsniai šiandien",
  "Stress": "Stresas",
  "Take it easier today?": "Šiandien lengviau?",
  "Tap what fits, skip what does not.": "Paliesk, kas tinka, kita praleisk.",
  "The month so far, the short version.": "Mėnuo iki šiol, trumpai.",
  "Today is a middling sort of day": "Šiandien šiaip sau diena",
