  "Turn it on": "Įjungti",
  "Twelve or more sessions. The gym should start charging you rent.": "Dvylika ar daugiau treniruočių. Sporto salė turėtų imti iš tavęs nuomą.",
  "Usually {0}": "Paprastai {0}",
  "Weeks with a workout": "Savaitės su treniruote",
  "When soreness is 1 or 2": "Kai raumenų skausmas 1 ar 2",
