  "When your numbers dip two weeks running (and your check-ins say tired, if you log them), Home asks.": "Kai tavo rezultatai krenta dvi savaites iš eilės (ir matavimai rodo nuovargį, jei juos žymi), Pagrindinis paklaus.",
  "You did it once": "Pavyko kartą",
  "You did it {0} times": "Pavyko {0} k.",
  "You were injured, so this week is excused. The streak kept going and no freeze was spent.": "Turėjai traumą, todėl ši savaitė pateisinta. Serija tęsiasi, užšaldymas neišleistas.",
  "You were sick, so this week is excused. The streak kept going and no freeze was spent.": "Sirgai, todėl ši savaitė pateisinta. Serija tęsiasi, užšaldymas neišleistas.",
  "You were travelling, so this week is excused. The streak kept going and no freeze was spent.": "Keliavai, todėl ši savaitė pateisinta. Serija tęsiasi, užšaldymas neišleistas.",
  "Your badges": "Tavo ženkleliai",
  "Your body and the floor. A table for rows, that’s it.": "Tavo kūnas ir grindys. Stalas prisitraukimams, ir viskas.",
  "Your check-ins say tired, and the numbers are not climbing.": "Matavimai rodo nuovargį, o rezultatai nekyla.",
  "Your numbers dipped for two weeks and your check-ins say tired.": "Tavo rezultatai krito dvi savaites, o matavimai rodo nuovargį.",
  "Your numbers dipped for two weeks running.": "Tavo rezultatai krito dvi savaites iš eilės.",
