  "{0} is in {1} from next time.": "{0} nuo kito karto yra {1}.",
  "{0} is in {1}, on the Skill ladder rule.": "{0} yra {1}, su įgūdžių kopėčių taisykle.",
  "{0} left this year.": {"one": "Šiemet liko {0}.", "few": "Šiemet liko {0}.", "many": "Šiemet liko {0}.", "other": "Šiemet liko {0}."},
  "{0} points to level {1}": "{0} tšk. iki {1} lygio",
