  "{0} streak badges": {"one": "{0} serijos ženklelis", "few": "{0} serijos ženkleliai", "many": "{0} serijos ženklelio", "other": "{0} serijos ženklelių"},
  "{0} week a year": "{0} savaitė per metus",
