  // --- AI Coach 1.4.5: setup, actions, data switches, connector (coach-146) ---
  "Add it as a custom connector in Claude or ChatGPT and sign in with openGym when it asks. Other assistants take a token from below.": "Pridėk jį kaip pasirinktinę jungtį Claude arba ChatGPT ir, kai paklaus, prisijunk su openGym. Kiti asistentai naudoja žetoną žemiau.",
  "Add “{0}” to my plan": "Pridėti „{0}“ į mano planą",
  "Add “{0}” to your exercises": "Pridėti „{0}“ prie tavo pratimų",
  "Added to your exercises": "Pridėta prie tavo pratimų",
  "After you say yes, it goes back to {0}. Only say yes if you just started this there.": "Kai sutiksi, grįš į {0}. Sutik tik jei ką tik ten tai pradėjai.",
  "Back to openGym": "Atgal į openGym",
  "Choose what it may read, and whether it may search the web": "Pasirink, ką jis gali skaityti ir ar gali ieškoti internete",
  "Claude, with an API key": "Claude su API raktu",
  "Code from OpenRouter": "Kodas iš OpenRouter",
  "Daily check-ins, sleep, resting heart rate, HRV and steps from your phone, and blood pressure. Off until you switch it on.": "Kasdieniai įrašai, miegas, ramybės pulsas, HRV ir žingsniai iš telefono bei kraujospūdis. Išjungta, kol neįjungsi.",
  "Estimated one-rep maxes of your main lifts over the last twelve weeks.": "Tavo pagrindinių pratimų apskaičiuotas vieno kartojimo maksimumas per dvylika savaičių.",
  "Find it for me": "Surask už mane",
  "For questions that need facts from outside your training, like a study or a product.": "Klausimams, kuriems reikia faktų ne iš tavo treniruočių, pvz., tyrimo ar produkto.",
  "From the routines library": "Iš rutinų bibliotekos",
  "GPT, with an API key": "GPT su API raktu",
  "Gemini, with a free tier to start": "Gemini su nemokamu planu pradžiai",
  "Get a key from {0}": "Gauk raktą iš {0}",
  "Health and how you feel": "Sveikata ir savijauta",
  "How it’s done": "Kaip atlikti",
  "It shows up under Settings → API tokens, where you can revoke it any time.": "Jį rasi Nustatymai → API žetonai, ten gali bet kada atšaukti.",
  "Looks for Ollama, LM Studio and llama.cpp on the machine running your openGym server and on this phone.": "Ieško Ollama, LM Studio ir llama.cpp kompiuteryje su tavo openGym serveriu ir šiame telefone.",
  "Nothing answered. Type its address below, like http://192.168.1.20:11434.": "Niekas neatsakė. Įrašyk adresą žemiau, pvz., http://192.168.1.20:11434.",
  "Ollama or LM Studio at home, nothing leaves your Wi-Fi": "Ollama ar LM Studio namie, niekas neišeina už tavo Wi-Fi",
  "On my network": "Mano tinkle",
  "One sign-in for Claude, GPT, Gemini and more": "Vienas prisijungimas Claude, GPT, Gemini ir kitiems",
  "OpenRouter makes a key just for this phone, billed to your OpenRouter credits. You can revoke it there any time.": "OpenRouter sukuria raktą tik šiam telefonui, apmokamą iš tavo OpenRouter kreditų. Ten gali bet kada jį atšaukti.",
  "Or paste a key": "Arba įklijuok raktą",
  "Paste a code instead": "Įklijuoti kodą",
  "Pick your AI": "Pasirink savo DI",
  "Remember": "Įsiminti",
