  "Switched off, it is left out of every request from now on.": "Išjungus, nuo šiol jis nebus siunčiamas jokioje užklausoje.",
  "Test it": "Išbandyti",
  "That doesn’t look like a code from OpenRouter.": "Tai neatrodo kaip OpenRouter kodas.",
